/**
 * Differential coverage for native custom aggregates (M5): the shipped stdev/variance factories plus a bespoke
 * order-insensitive n-ary test aggregate must return identical results with the native engine on and off, including
 * DISTINCT, grouped/global, mixed with built-in aggregates, and the empty-input global group.
 */
@Timeout(value = 120, unit = TimeUnit.SECONDS)
public class LmdbNativeCustomAggregateTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String PREFIX = "PREFIX ex: <" + EX + ">\n";
	private static final String NARY_IRI = "http://example.com/aggregate#weightedSum";

	/** Order-insensitive n-ary test aggregate: sum of (?v * ?w) over the group. */
	private static final AggregateNAryFunctionFactory WEIGHTED_SUM = new AggregateNAryFunctionFactory() {
		@Override
		public String getIri() {
			return NARY_IRI;
		}

		@Override
		public int getMinNumberOfArguments() {
			return 2;
		}

		@Override
		public int getMaxNumberOfArguments() {
			return 2;
		}

		@Override
		public AggregateNAryFunction buildFunction(BiFunction<Integer, BindingSet, Value> evaluationStepByIndex) {
			return new AggregateNAryFunction<WeightedSumCollector, Value>(evaluationStepByIndex) {
				@Override
				public void processAggregate(BindingSet bindingSet, Predicate<List<Value>> distinctTuple,
						WeightedSumCollector agv) {
					Value v = evaluate(0, bindingSet);
					Value w = evaluate(1, bindingSet);
					if (v == null || w == null || !v.isLiteral() || !w.isLiteral()) {
						return;
					}
					if (!distinctTuple.test(List.of(v, w))) {
						return;
					}
					try {
						agv.sum = agv.sum.add(new BigDecimal(v.stringValue())
								.multiply(new BigDecimal(w.stringValue())));
					} catch (NumberFormatException e) {
						// skip non-numeric inputs
					}
				}
			};
		}

		@Override
		public AggregateCollector getCollector() {
			return new WeightedSumCollector();
		}
	};

	private static final class WeightedSumCollector implements AggregateCollector {
		BigDecimal sum = BigDecimal.ZERO;

		@Override
		public Value getFinalValue() {
			return SimpleValueFactory.getInstance().createLiteral(sum.toPlainString(), XSD.DECIMAL);
		}
	}

	@BeforeAll
	public static void registerNAry() {
		CustomAggregateNAryFunctionRegistry.getInstance().add(WEIGHTED_SUM);
	}

	@AfterAll
	public static void unregisterNAry() {
		CustomAggregateNAryFunctionRegistry.getInstance().remove(WEIGHTED_SUM);
	}

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI value = vf.createIRI(EX, "value");
			IRI weight = vf.createIRI(EX, "weight");
			IRI group = vf.createIRI(EX, "group");
			for (int i = 0; i < 12; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				conn.add(s, value, vf.createLiteral(i % 5 + i * 0.25));
				conn.add(s, weight, vf.createLiteral(1 + i % 3));
				conn.add(s, group, vf.createIRI(EX, "g" + i % 3));
			}
			// duplicated values for DISTINCT sensitivity
			conn.add(vf.createIRI(EX, "s0"), value, vf.createLiteral(0.0d));
			conn.add(vf.createIRI(EX, "dup"), value, vf.createLiteral(2.25d));
			conn.add(vf.createIRI(EX, "dup"), group, vf.createIRI(EX, "g1"));
			// a non-numeric value: the statistical aggregates raise a type error for it
			conn.add(vf.createIRI(EX, "bad"), value, vf.createLiteral("not numeric"));
			conn.add(vf.createIRI(EX, "bad"), group, vf.createIRI(EX, "g2"));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> result = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			List<String> canonical = new ArrayList<>(result.size());
			for (BindingSet bs : result) {
				TreeMap<String, String> sorted = new TreeMap<>();
				for (Binding binding : bs) {
					sorted.put(binding.getName(), binding.getValue().toString());
				}
				canonical.add(sorted.toString());
			}
			return canonical;
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void assertSameRows(String query) {
		List<String> generic = rows(query, false);
		assertThat(rows(query, true))
				.as("native vs generic rows for:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	private void assertSameRowsNonEmpty(String query) {
		List<String> generic = rows(query, false);
		assertThat(generic).as("generic oracle must produce rows:\n%s", query).isNotEmpty();
		assertThat(rows(query, true))
				.as("native vs generic rows for:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	@Test
	public void stdevGlobalAndGrouped() {
		assertSameRowsNonEmpty(PREFIX + "SELECT (<http://rdf4j.org/aggregate#stdev>(?v) AS ?sd) WHERE { "
				+ "?s ex:value ?v . FILTER(isNumeric(?v)) }");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?g (<http://rdf4j.org/aggregate#stdev>(?v) AS ?sd) WHERE { "
				+ "?s ex:group ?g ; ex:value ?v . FILTER(isNumeric(?v)) } GROUP BY ?g");
	}

	@Test
	public void varianceWithDistinct() {
		assertSameRowsNonEmpty(PREFIX + "SELECT ?g (<http://rdf4j.org/aggregate#variance>(DISTINCT ?v) AS ?var) "
				+ "WHERE { ?s ex:group ?g ; ex:value ?v . FILTER(isNumeric(?v)) } GROUP BY ?g");
	}

	@Test
	public void customMixedWithBuiltInAggregates() {
		assertSameRowsNonEmpty(PREFIX + "SELECT ?g (<http://rdf4j.org/aggregate#stdev>(?v) AS ?sd) "
				+ "(SUM(?v) AS ?sum) (COUNT(?v) AS ?n) WHERE { "
				+ "?s ex:group ?g ; ex:value ?v . FILTER(isNumeric(?v)) } GROUP BY ?g");
	}

	@Test
	public void nAryCustomAggregate() {
		assertSameRowsNonEmpty(PREFIX + "SELECT (<" + NARY_IRI + ">(?v, ?w) AS ?ws) WHERE { "
				+ "?s ex:value ?v ; ex:weight ?w . }");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?g (<" + NARY_IRI + ">(?v, ?w) AS ?ws) WHERE { "
				+ "?s ex:group ?g ; ex:value ?v ; ex:weight ?w . } GROUP BY ?g");
		assertSameRowsNonEmpty(PREFIX + "SELECT ?g (<" + NARY_IRI + ">(DISTINCT ?v, ?w) AS ?ws) WHERE { "
				+ "?s ex:group ?g ; ex:value ?v ; ex:weight ?w . } GROUP BY ?g");
	}

	@Test
	public void customAggregateOverExpressionArgument() {
		assertSameRowsNonEmpty(PREFIX + "SELECT (<http://rdf4j.org/aggregate#stdev>(?v * 2) AS ?sd) WHERE { "
				+ "?s ex:value ?v . FILTER(isNumeric(?v)) }");
	}

	@Test
	public void emptyInputGlobalGroup() {
		assertSameRows(PREFIX + "SELECT (<http://rdf4j.org/aggregate#stdev>(?v) AS ?sd) WHERE { "
				+ "?s ex:doesNotExist ?v . }");
	}

	@Test
	public void typeErrorInputsMatchGeneric() {
		// the "not numeric" literal reaches the statistical aggregate; both engines must agree on the outcome
		assertSameRows(PREFIX + "SELECT ?g (<http://rdf4j.org/aggregate#stdev>(?v) AS ?sd) WHERE { "
				+ "?s ex:group ?g ; ex:value ?v . } GROUP BY ?g");
	}

	@Test
	public void unknownCustomAggregateStillErrorsLikeGeneric() {
		String query = PREFIX + "SELECT (<http://example.com/aggregate#unknown>(?v) AS ?x) WHERE { "
				+ "?s ex:value ?v . }";
		org.assertj.core.api.Assertions.assertThatThrownBy(() -> rows(query, true))
				.hasMessageContaining("aggregate");
		org.assertj.core.api.Assertions.assertThatThrownBy(() -> rows(query, false))
				.hasMessageContaining("aggregate");
	}
}
